#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Units {
    #[default]
    Invalid = 0,
    Metric = 1,
    Imperial = 2,
}

impl From<Units> for FbsUnits {
    fn from(val: Units) -> Self {
        match val {
            Units::Invalid => FbsUnits::Invalid,
            Units::Metric => FbsUnits::Metric,
            Units::Imperial => FbsUnits::Imperial,
        }
    }
}

impl From<FbsUnits> for Units {
    fn from(fbs: FbsUnits) -> Self {
        match fbs.0 {
            0 => Self::Invalid,
            1 => Self::Metric,
            2 => Self::Imperial,
            _ => panic!("Invalid value {} when constructing Units", fbs.0),
        }
    }
}

#[derive(Default, PartialEq, Debug, Clone)]
pub struct UserPreferences {
    pub center: Option<Point>,
    pub default_area_report_template: Option<ObjectId>,
    pub homepage_usecase_id: Option<ObjectId>,
    pub timezone: Option<String>,
    pub units: Units,
    pub zoom: f32,
}

impl UserPreferences {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsUserPreferences<'a>> {
        use crate::types::generated::user_preferences_generated::UserPreferencesBuilder as FbsUserPreferencesBuilder;

        let center_offset = self.center.as_ref().map(|o| o.serialize_to(builder));
        let default_area_report_template_offset = self
            .default_area_report_template
            .as_ref()
            .map(|o| o.serialize_to(builder));
        let homepage_usecase_id_offset = self
            .homepage_usecase_id
            .as_ref()
            .map(|o| o.serialize_to(builder));
        let timezone_offset = self.timezone.as_ref().map(|s| builder.create_string(s));

        let mut bldr = FbsUserPreferencesBuilder::new(builder);
        if let Some(offset) = center_offset {
            bldr.add_center(offset);
        }
        if let Some(offset) = default_area_report_template_offset {
            bldr.add_default_area_report_template(offset);
        }
        if let Some(offset) = homepage_usecase_id_offset {
            bldr.add_homepage_usecase_id(offset);
        }
        if let Some(offset) = timezone_offset {
            bldr.add_timezone(offset);
        }
        bldr.add_units(FbsUnits::from(self.units));
        bldr.add_zoom(self.zoom);
        bldr.finish()
    }
}

impl From<FbsUserPreferences<'_>> for UserPreferences {
    fn from(fbs: FbsUserPreferences<'_>) -> Self {
        let center = fbs.center().map(Point::from);
        let default_area_report_template = fbs.default_area_report_template().map(ObjectId::from);
        let homepage_usecase_id = fbs.homepage_usecase_id().map(ObjectId::from);
        let timezone = fbs.timezone().map(ToOwned::to_owned);
        let units = Units::from(fbs.units());
        let zoom = fbs.zoom();
        Self {
            center,
            default_area_report_template,
            homepage_usecase_id,
            timezone,
            units,
            zoom,
        }
    }
}

